/* This is getqinfo example header maker */
/* Compile with cc -o getqinfo -lqb getqinfo.c  */
/* It doesn't do anything to the data, but
   shows how to get at the information and use
   the routines           */
#include <stdio.h>
#include <IN/backend.h>
#include <IN/standard.h>
#include <string.h>
char *qdate;
char *cmdline;
char *to;
char *devname;
char *title;
char *qname;
char *qdname;
char *from;
char *at;
char *enqflags;
int   mail_only;
int   jobno;
main(argc,argv)
unsigned argc;
char **argv;
{
  int   rc, i, c;
  char* pfile;
  FILE *pf;
/*  This is an obligatory routine for getting access to
    all the other routines - log_init           */
  rc = log_init();
  if (rc == -1)
  {
/* So we see something if log_init fails - Output Error */
        printf("ERROR\n");
        exit(1);
  }
  else
  {
/*  Some of the standard backend subroutine calls are */
/*  Then are described in info explorer                 */
    from      = get_from();
    title     = get_title();
    jobno     = get_job_number();
/* Return information to shell script   */
        printf("%s %s %d\n",from,title,jobno);
  }
  exit(0);
}

#/bin/ksh
# This testpr.sh script is designed to print overlays
# when initiated by HCON, but should also work for other
# types of printing.
#
while getopts :J:L:X:Z:b:ci:j:l:p:f:s:t:u:v:w:x:y:z: arguments
do
 case $arguments in
## $OPTARG
      X) Xflags="-X $OPTARG" ;;
      J) Jflags="-J $OPTARG" ;;
      L) Lflags="-L $OPTARG" ;;
      Z) Zflags="-Z $OPTARG" ;;
      b) bflags="-b $OPTARG" ;;
      c) cflags="-c $OPTARG" ;;
      f) fflags="-f $OPTARG" ;;
      g) gflags="-g $OPTARG" ;;
      i) iflags="-i $OPTARG" ;;
      j) jflags="-j $OPTARG" ;;
      l) lflags="-l $OPTARG" ;;
      p) pflags="-p $OPTARG" ;;
      s) sflags="-s $OPTARG" ;;
      t) tflags="-t $OPTARG" ;;
      u) uflags="-u $OPTARG" ;;
      v) vflags="-v $OPTARG" ;;
      w) wflags="-w $OPTARG" ;;
      x) xflags="-x $OPTARG" ;;
      y) yflags="-y $OPTARG" ;;
      z) zflags="-z $OPTARG" ;;
      \?)  ;;
 esac
done
 ((current_position = OPTIND -1))
 shift $current_position
date >> /tmp/flags.out
###############  Call C code to get queue info ###################
    FT=`/usr/local/bin/getqinfo`
    integer j=0
    typeset  fr
    for ft in $FT
     do
        fr[j]=$ft
        let j=j+1
     done
